// Preset profile avatars — users pick one instead of uploading an image.
// The SVGs live in public/avatars/ (generated by scripts/generate-avatars.mjs).
// `avatar_url` is stored as the relative path, which the plain <img> in
// UserAvatar renders directly.

export type PresetAvatar = { id: string; label: string };

export const PRESET_AVATARS: {
  cats: PresetAvatar[];
  movie: PresetAvatar[];
} = {
  cats: [
    { id: "cat-black", label: "Black cat" },
    { id: "cat-orange", label: "Orange tabby" },
    { id: "cat-gray", label: "Gray cat" },
    { id: "cat-white", label: "White cat" },
    { id: "cat-brown", label: "Brown cat" },
    { id: "cat-cream", label: "Golden cat" },
    { id: "cat-calico", label: "Calico cat" },
    { id: "cat-siamese", label: "Siamese cat" },
    { id: "cat-pink", label: "Cyberpunk cat" },
    { id: "cat-cosmic", label: "Cosmic cat" },
    { id: "cat-zombie", label: "Zombie cat" },
    { id: "cat-gold", label: "Gold cat" },
  ],
  movie: [
    { id: "clapperboard", label: "Clapperboard" },
    { id: "popcorn", label: "Popcorn" },
    { id: "ghost", label: "Ghost" },
    { id: "robot", label: "Robot" },
    { id: "alien", label: "Alien" },
    { id: "reel", label: "Film reel" },
  ],
};

const ALL_IDS = new Set(
  [...PRESET_AVATARS.cats, ...PRESET_AVATARS.movie].map((a) => a.id),
);

export function isPresetAvatarId(id: string): boolean {
  return ALL_IDS.has(id);
}

export function presetAvatarPath(id: string): string {
  return `/avatars/${id}.svg`;
}

/** Inverse of `presetAvatarPath`: recover the preset id from a stored avatar
 * path, or null if it isn't one of our presets (e.g. a legacy uploaded URL). */
export function presetIdFromPath(path: string | null | undefined): string | null {
  if (!path) return null;
  const id = /^\/avatars\/(.+)\.svg$/.exec(path)?.[1];
  return id && isPresetAvatarId(id) ? id : null;
}
